-- =====================================================================
-- 0003_estimating_seed.sql
-- seed_default_estimating(company_id): loads the starter price book and the
-- "10x10 L-shape - shaker + quartz" template for one company.
-- Call it when a company is created (onboarding server action, service role)
-- and from supabase/seed.sql for local dev. Safe to call twice: it does nothing
-- if the company already has catalog categories.
--
-- ALL unit costs are SAMPLE placeholders (they mirror the estimate workbook).
-- Replace them in Settings > Price book before quoting real jobs.
-- Generated by gen_seed.py - edit the generator, not this file.
-- =====================================================================
create or replace function public.seed_default_estimating(p_company_id uuid)
