  select p_company_id, v.* from (values
      ('1. Cabinetry', 'Cabinets per the cabinet list, fillers, panels, crown, light rail, toe kick, hardware', 1, false),
      ('2. Countertop', 'Quartz top, edge, sink cutout, faucet holes, template and install', 2, false),
